B.a1g={"snd-electricite-acces":0,"masterplan-electricite-transition":1,"vision-electricite-prix":2,"vision-electricite-capacites":3,"snd-sante-soins":4,"snd-sante-medicaments":5,"masterplan-sante-proximite":6,"vision-sante-couverture":7,"snd-industrie-valorisation":8,"masterplan-industrie-zones":9,"masterplan-industrie-production":10,"vision-industrie-filieres":11,"masterplan-peche-gouvernance":12,"masterplan:pdf99:right:extract:1206":13}
B.ZC=s(["Renforcer le r\xe9seau de transport et de distribution.","Acc\xe9l\xe9rer l\u2019\xe9lectrification rurale.","Am\xe9liorer la tarification et les subventions.","D\xe9velopper les \xe9nergies renouvelables et alternatives."],t.s)
B.a8j=new A.fM(B.af,B.ZC,"Garantir l\u2019acc\xe8s universel \xe0 l\u2019\xe9lectricit\xe9 \xe0 moindre co\xfbt en 2029, en renfor\xe7ant les r\xe9seaux, l\u2019\xe9lectrification rurale et les \xe9nergies renouvelables.")
B.Sg=s(["Atteindre 40 % d\u2019\xe9nergies renouvelables dans le mix \xe9nerg\xe9tique en 2030.","D\xe9velopper l\u2019\xe9lectricit\xe9 produite \xe0 partir du gaz et pr\xe9voir des capacit\xe9s nucl\xe9aires.","\xc9tendre et renforcer les r\xe9seaux, notamment en milieu rural.","R\xe9duire les pertes \xe9lectriques et am\xe9liorer l\u2019efficacit\xe9 \xe9nerg\xe9tique."],t.s)
B.a7h=new A.fM(B.af,B.Sg,"Assurer un acc\xe8s universel \xe0 une \xe9lectricit\xe9 durable et moins ch\xe8re en d\xe9veloppant les renouvelables et le gaz, en \xe9tendant les r\xe9seaux et en r\xe9duisant les pertes.")
B.UC=s(["Prix moyen de vente aux clients vis\xe9 : inf\xe9rieur \xe0 60 FCFA/kWh, soit pr\xe8s de deux fois moins qu\u2019en 2024.","Acc\xe8s vis\xe9 : 100 % en milieu urbain comme en milieu rural.","Capacit\xe9 de production : de 1 945 MW en 2023 \xe0 plus de 12 000 MW en 2050, dont plus de 40 % de renouvelables."],t.s)
B.a71=new A.fM(B.af,B.UC,"Rendre l\u2019\xe9lectricit\xe9 moins ch\xe8re et accessible \xe0 tous \xe0 l\u2019horizon 2050, en augmentant les capacit\xe9s de production et en d\xe9veloppant les renouvelables, le gaz et progressivement le nucl\xe9aire.")
B.Yw=s(["Capacit\xe9 install\xe9e : de 1 945 MW en 2023 \xe0 plus de 12 000 MW en 2050.","Part des \xe9nergies renouvelables vis\xe9e : plus de 40 %.","Recourir au gaz et introduire progressivement le nucl\xe9aire, avec la disparition pr\xe9vue du fuel lourd, du gasoil et du charbon."],t.s)
B.a7S=new A.fM(B.af,B.Yw,"Accro\xeetre la production \xe9lectrique d\u2019ici 2050 gr\xe2ce au d\xe9veloppement des renouvelables, au recours au gaz et \xe0 l\u2019introduction progressive du nucl\xe9aire.")
B.Qm=s(["\xc9tendre la carte sanitaire, notamment les \xe9tablissements sanitaires militaires.","Renforcer les \xe9quipements et le personnel m\xe9dical sp\xe9cialis\xe9.","Renforcer la lutte contre les maladies non transmissibles.","Am\xe9liorer l\u2019acc\xe8s aux urgences et aux traitements de base."],t.s)
B.a77=new A.fM(B.af,B.Qm,"Faciliter l\u2019acc\xe8s \xe0 des soins de qualit\xe9 en \xe9tendant la carte sanitaire, en renfor\xe7ant les \xe9quipements et le personnel sp\xe9cialis\xe9, et en am\xe9liorant les urgences.")
B.Q9=s(["Produire localement 30 % des besoins nationaux en m\xe9dicaments, en ciblant les mol\xe9cules prioritaires.","Renforcer la r\xe9gulation pharmaceutique et rendre le cadre r\xe9glementaire attractif.","Cr\xe9er des laboratoires de recherche et un cadre juridique pour les traitements \xe0 base de plantes.","Int\xe9grer One Health (une seule sant\xe9 : sant\xe9 humaine, animale et environnementale) dans les politiques sanitaires."],t.s)
B.a6P=new A.fM(B.af,B.Q9,"Renforcer la souverainet\xe9 sanitaire en soutenant la production locale de m\xe9dicaments, la recherche et l\u2019encadrement pharmaceutique.")
B.Uw=s(["P\xe9nurie de professionnels de sant\xe9.","Disparit\xe9s d\u2019acc\xe8s aux soins entre zones urbaines et rurales."],t.s)
B.Rx=s(["Construire des h\xf4pitaux de niveau 3 dans toutes les r\xe9gions et moderniser les structures existantes.","Transformer les centres de sant\xe9 de r\xe9f\xe9rence des districts en h\xf4pitaux \xe9quip\xe9s de toutes les sp\xe9cialit\xe9s.","Doubler le nombre de m\xe9decins, d\u2019infirmi\xe8res et de sages-femmes.","D\xe9centraliser la gestion et d\xe9velopper la sant\xe9 num\xe9rique et mobile."],t.s)
B.a88=new A.fM(B.Uw,B.Rx,"R\xe9duire les disparit\xe9s d\u2019acc\xe8s aux soins par de nouveaux h\xf4pitaux, la modernisation des structures existantes et le renforcement du personnel dans les r\xe9gions.")
B.Rv=s(["Moderniser les infrastructures dans toutes les r\xe9gions et d\xe9centraliser les soins.","Cr\xe9er une assurance maladie nationale \xe9quitable, reposant sur un financement durable.","Renforcer la pr\xe9vention, la t\xe9l\xe9m\xe9decine et la prise en charge personnalis\xe9e."],t.s)
B.a6C=new A.fM(B.af,B.Rv,"Atteindre une couverture sanitaire universelle en 2050 en modernisant les infrastructures, en d\xe9centralisant les soins et en cr\xe9ant une assurance maladie nationale \xe9quitable.")
B.Zk=s(["Mettre en place un cadre fiscal plus favorable.","Renforcer la promotion des investissements et des exportations."],t.s)
B.a6I=new A.fM(B.af,B.Zk,"Soutenir la valorisation locale des industries manufacturi\xe8res et artisanales gr\xe2ce \xe0 une fiscalit\xe9 plus favorable et \xe0 la promotion des investissements et des exportations.")
B.V7=s(["D\xe9velopper 1 000 hectares de zones \xe9conomiques sp\xe9ciales et de plateformes manufacturi\xe8res.","Renforcer les p\xf4les de Touba, Diamniadio, Diass et Ndayane, ainsi que le parc automobile."],t.s)
B.a7t=new A.fM(B.af,B.V7,"Renforcer la production industrielle par de nouvelles zones \xe9conomiques sp\xe9ciales, des plateformes manufacturi\xe8res et la consolidation des p\xf4les existants.")
B.RS=s(["Augmentation de la production industrielle vis\xe9e : +75 % d\u2019ici 2034.","Part des exportations manufacturi\xe8res dans les exportations totales : passer de 15 % \xe0 35 %."],t.s)
B.a7I=new A.fM(B.af,B.RS,"Le plan fixe des cibles de hausse de la production industrielle et de la part des exportations manufacturi\xe8res pour renforcer la transformation de l\u2019\xe9conomie.")
B.Xb=s(["Cinq fili\xe8res envisag\xe9es : pharmacie, cuir, textile, assemblage et recyclage des d\xe9chets.","D\xe9velopper des zones \xe9conomiques sp\xe9ciales le long des corridors logistiques.","Attirer les investissements priv\xe9s gr\xe2ce au foncier, \xe0 la connectivit\xe9 et aux infrastructures de production."],t.s)
B.a7r=new A.fM(B.af,B.Xb,"B\xe2tir d\u2019ici 2050 une plateforme industrielle comp\xe9titive pour le march\xe9 r\xe9gional, en soutenant cinq fili\xe8res et des zones \xe9conomiques sp\xe9ciales le long des corridors logistiques.")
B.Zf=s(["Identifier les p\xeacheurs, immatriculer les pirogues et renouveler progressivement la flotte artisanale.","Adapter les quotas des navires industriels au niveau des stocks.","Faire respecter les repos biologiques et les aires prot\xe9g\xe9es.","Encadrer les usines de farine et d\u2019huile de poisson pour pr\xe9venir la surexploitation des petits p\xe9lagiques."],t.s)
B.a6Y=new A.fM(B.af,B.Zf,"Structurer la p\xeache et l\u2019aquaculture en identifiant les professionnels, en renouvelant la flotte et en adaptant les quotas et les contr\xf4les pour pr\xe9server les ressources marines.")
B.QN=s(["Pertes non techniques d\u2019\xe9lectricit\xe9.","Recouvrement des cr\xe9ances \xe0 am\xe9liorer.","R\xe9forme institutionnelle de la SENELEC inachev\xe9e."],t.s)
B.Va=s(["Renforcer les capacit\xe9s de planification et de gestion des ressources humaines pour anticiper les m\xe9tiers du futur."],t.s)
B.a87=new A.fM(B.QN,B.Va,"Pr\xe9parer une transition \xe9nerg\xe9tique juste et durable en renfor\xe7ant la planification et la gestion des ressources humaines du secteur \xe9lectrique.")
